export default function (pi) {
  let promptOptions;
  let toolTokens;
  pi.on("before_agent_start", (event) => {
    promptOptions = event.systemPromptOptions;
    const active = new Set(pi.getActiveTools());
    toolTokens = pi.getAllTools().filter((tool) => active.has(tool.name)).reduce(
      (total, tool) => total + Math.ceil(JSON.stringify({ name: tool.name, description: tool.description, parameters: tool.parameters }).length / 4), 0);
    return { systemPrompt: "FORCED_POLICY" };
  });
  pi.on("context_with_system", (event) => {
    const custom = event.messages.find((message) => message.role === "custom" && message.customType === "posthorse-guidance");
    const sectioned = event.messages.find((message) => message.role === "system" && typeof message.sections?.posthorse === "string");
    let wrapped;
    if (custom) {
      const guidance = typeof custom.content === "string" ? custom.content : custom.content.map((p) => p.text ?? "").join("\n");
      wrapped = `<posthorse>\n${guidance}\n</posthorse>`;
    } else if (sectioned) {
      wrapped = sectioned.sections.posthorse;
    } else {
      throw new Error("guidance missing");
    }
    const guidanceTokens = Math.ceil(wrapped.length / 4);
    const promptTokens = 32768 - 1000 - toolTokens - guidanceTokens - 2250;
    if (!(promptTokens > 0)) throw new Error("no room");
    promptOptions.forceSystemPrompt = "s".repeat(promptTokens * 4);
    if (event.messages[0]?.role !== "system") throw new Error("no system message");
    return { messages: [{ ...event.messages[0], content: promptOptions.forceSystemPrompt }, ...event.messages.slice(1)] };
  });
}
